/** Header Date Calendar Icon with Dynamic Day Number */
export function IconHeaderCalendar({
  size = 17,
  date,
  day,
  strokeWidth = 1.8,
  className = '',
  ...props
}) {
  const dayNumber = day ?? (date ? new Date(date).getDate() : new Date().getDate());
  const isTwoDigits = String(dayNumber).length > 1;

  return (
    <svg
      width={size}
      height={size}
      strokeWidth={strokeWidth}
      className={className}
      {...defaultSvgProps}
      {...props}
    >
      {/* Top hanger pegs */}
      <path d="M8 2v3M16 2v3" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" />

      {/* Calendar card outline */}
      <rect
        x="3.5"
        y="4"
        width="17"
        height="17"
        rx="3"
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
      />

      {/* Day number that dynamically changes with date */}
      <text
        x="12"
        y="13"
        textAnchor="middle"
        dominantBaseline="central"
        fill="currentColor"
        stroke="none"
        fontSize={isTwoDigits ? '9.5' : '10.5'}
        fontWeight="600"
        fontFamily="system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
        style={{ fontVariantNumeric: 'tabular-nums', letterSpacing: '-0.02em' }}
      >
        {dayNumber}
      </text>
    </svg>
  );
}

